  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "完整定义请求生命期、分支、授权尝试、逻辑位置、视图与物理槽代次，区分已知 token、全层有效 KV、业务提交和最后使用；输入、构造输出及长期状态均明确。长期页表和两类引用使 k 的含义具有资源依据。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "κ=(r,β,g,p)=((request_id,lifetime_id),branch_id,attempt,logical_position)。"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "普通推进满足 0≤k≤n；已知 token 与已完成 KV 不同。新采样 token 可以已经进入 x，却尚未计算自己的 KV。"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "机制输入是请求/分支账、候选工作、资源与版本快照；构造输出是不可变视图 V_t 和执行记录 E_t。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "已确认输入、因果可见性、版本相容、写权、唯一提交权及物理排空构成合法条件；单分支单未释放视图、整视图完成门和固定槽保护明确属于保守选择。KV_ONLY/SAMPLE、完整 KV 命中缺 logits、空输入和终止边界均有处理，未把 ORCA 的历史执行组织提升为数学限制。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "普通推进选择 [p0,p1)=[k,k+q)，其中 q 为正整数，p1≤n，输入已经确认，历史与因果 mask 可用，写区具有独占写权或合法 COW。"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "混合版本只有在执行器逐行支持相应权重地址、页表与数值路径时才合法，否则分桶。"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "epoch 拒绝旧结果，最后使用条件防止旧物理访问；两者解决不同问题。"
        }
      ]
    },
    "algorithm": {
      "assessment": "sufficient",
      "reason": "构造、原子发布、准备、提交、完成、分支事务与回收形成闭合路径。F07 已由发布事务中的 active_view 登记及未提交/准备失败后的 business_done、排空和清绑定步骤修复。F08 已在三条保留 KV 路径统一建立长期拥有权，并限制 finalize 只解除执行引用。F09 已展开首层输入、各层历史及新增 KV、hidden 传递、末层 logits 和逐层逐位置完成覆盖。当前文本足以解释正常推进与拒绝路径，三项旧阻塞均关闭。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "owner[σ]←view_id；对每个入选段令 L[r,β].active_view←view_id"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "令所有尚未解析段为 aborted，business_done←true；k/n/RNG/输出不变"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "所有保留新 KV 的事务都使用同一拥有权步骤：先核对 E 保护的新页及全层写入证据，在事务内为有效范围建立或转移 (r,β) 的长期拥有者引用，发布全层页表，再发布 k 和提交键。"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "第 ℓ 层的历史 K/V 来自 O 中该分支的第 ℓ 层 [0,p0)，本轮新 K/V 来自该层输入 h^(ℓ−1) 的投影，不来自其他层的历史，也不来自兄弟分支。"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "算法 2 的全层门要求对每个必要 (ℓ,κ) 完整覆盖，κ 已含逻辑位置 p；不能用“该层发生过一次写入”代表整个段完成。"
        }
      ]
    },
    "cost": {
      "assessment": "sufficient",
      "reason": "六类成本均有条件化解释。主机复杂度限定为准备、校验及引用移交；attention 公式按每段合法 query-key 对数乘 QK/PV 的每对 4d FLOPs，层数和 query heads 因子一致。逻辑搬运字节、实际内存事务、通信副本、关键路径与唯一物理驻留分开，COW 和长期引用的容量含义明确；没有用符号模型推断硬件性能。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "准备操作量期望为 O(LF+RG+B+H+P)，完成校验及引用移交为 O(L+T+H+P)"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "普通稠密 attention 的 QK 与 PV 主工作量约为 4NℓHq d·Σ_b[q_b h_b+q_b(q_b+1)/2] 个浮点操作"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "时间应沿真实关键路径计算；独立阶段可以重叠，共享 CPU、内存链路或 NIC 的阶段不能各取独占带宽后再宣称完全重叠。"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "共享 KV 页只计一次物理容量，但每个拥有者和执行引用仍需责任记录。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "说明活跃集合、图重放、准备瓶颈、慢消费者、版本变化与迁移改变后应如何调整表示和责任组织。更深流水、搜索树、递归及覆盖状态的扩展条件清楚；保持身份和最后使用约束，同时允许调整槽、段表、输出池或放弃不相容缓存。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "更深流水必须增加依赖、未确认进度和提交次序，不能直接删除这一限制。"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "若实测准备已占关键路径，可考虑段表、增量更新或独立输出池；若慢消费者占满槽，应调整有界输出与背压策略，而非提前删除其责任。"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "模型或 processor 改变后，不相容状态必须重建。"
        }
      ]
    },
    "diagnosis": {
      "assessment": "sufficient",
      "reason": "竞争解释配有控制改变和不同预测；检查参考由原始分支账及固定层域产生，能够拒绝同步错配、漏身份、漏绑定、漏 owner 和消费者碰撞。缺层、缺单位置、缺 logits 与不可见证书通过实际完成门拒绝。明确区分符号状态证据、设备事实和使用效果，反证后的修正方向具体。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "检查参考必须独立于被测视图：从原始请求/分支账与明确选中范围重建完整 κ、token、参数、版本、采样资格和输出序号，再核对实际行及派生数组。"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "页参考从分支 k 和固定层域导出每个必须存在的逻辑位置，检查相容页、长期拥有权与不可复用性，不以 E 尚未释放掩盖 owner 缺失。"
        },
        {
          "path": "knowledge/system-semantics/request-batch-identity.md",
          "quote": "反证应修改对应机制解释，不能通过删请求或放宽分母使结果通过。"
        }
      ]
    }
  },
  "findings": [],
  "limitations": [
    "检查仅覆盖确定性 CPU 符号身份、状态及页引用模型；不计算真实 hidden、K/V 或 logits，不证明数值等价、采样分布及 PRNG 质量。",
    "逐层写入、可见性、排空和消费者结束由模型事件提供；真实 GPU、跨 stream、DMA、网络及通信 API 的完成范围仍需实际执行路径证据。",
    "真实分页与共享尾页 COW、完整 KV 命中后的重算、递归或窗口覆盖状态、搜索共同接受、持久事务及分布式授权未由本脚本验证；正文已声明相应范围或委托相关协议。",
    "S-VLLM-SCHED 仅核对所供来源说明，没有上游源码归档供独立核验；ORCA 与 OTel 的核对范围为所供全文提取文本，不包含另行检查 PDF 图像或归档字节。",
    "本次审阅未自行运行 Python 或重新计算磁盘哈希；执行结论依据用户提供、绑定当前脚本及正文摘要的 actual_preflight，未把作者阶段未执行的检查记为通过。"
  ],
